local STACK_ALPHABET="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local STACK_CACHE,STACK_CACHE_AGE={},{ }
local STACK_CACHE_LIMIT=16
local stackCacheClock=0
local function stackDecode64(chunks)
  local text=table.concat(chunks)
  local out={}
  for i=1,#text,4 do
    local a=string.find(STACK_ALPHABET,text:sub(i,i),1,true)-1
    local b=string.find(STACK_ALPHABET,text:sub(i+1,i+1),1,true)-1
    local cchar=text:sub(i+2,i+2)
    local dchar=text:sub(i+3,i+3)
    local c=cchar=="=" and 0 or string.find(STACK_ALPHABET,cchar,1,true)-1
    local d=dchar=="=" and 0 or string.find(STACK_ALPHABET,dchar,1,true)-1
    out[#out+1]=string.char(a*4+math.floor(b/16))
    if cchar~="=" then out[#out+1]=string.char((b%16)*16+math.floor(c/4)) end
    if dchar~="=" then out[#out+1]=string.char((c%4)*64+d) end
  end
  return table.concat(out)
end
local function stackDecodeCapsule(chunks,seed)
  local masked=stackDecode64(chunks)
  local pieces={}
  local state=seed
  for first=1,#masked,4096 do
    local piece={}
    local last=math.min(first+4095,#masked)
    for index=first,last do
      state=(state*48271)%2147483647
      piece[#piece+1]=string.char((string.byte(masked,index)-state%256+256)%256)
    end
    pieces[#pieces+1]=table.concat(piece)
  end
  local data=table.concat(pieces)
  local position=1
  local function readByte()
    local value=string.byte(data,position)
    if not value then error("truncated Ravel stack capsule") end
    position=position+1
    return value
  end
  local function readUInt()
    local value,multiplier=0,1
    for _=1,8 do
      local byte=readByte()
      value=value+(byte%128)*multiplier
      if byte<128 then return value end
      multiplier=multiplier*128
    end
    error("invalid Ravel stack capsule integer")
  end
  local function readBlob()
    local length=readUInt()
    local value=data:sub(position,position+length-1)
    if #value~=length then error("truncated Ravel stack capsule blob") end
    position=position+length
    return value
  end
  if readByte()~=3 then error("unsupported Ravel stack capsule version") end
  local parameterCount=readUInt()
  local registerCount=readUInt()
  local dialect=readByte()
  if dialect>1 then error("invalid Ravel stack operand dialect") end
  local opcodeCount=readUInt()
  if opcodeCount~=26 then error("invalid Ravel stack opcode count") end
  local opcodeMap={}
  for logical=1,opcodeCount do
    local wire=readByte()
    if wire<1 or wire>opcodeCount or opcodeMap[wire] then error("invalid Ravel stack opcode map") end
    opcodeMap[wire]=logical
  end
  local constants={}
  local constantCount=readUInt()
  for index=1,constantCount do
    local kind=readByte()
    if kind==0 then
      constants[index]=nil
    elseif kind==1 then
      constants[index]=readByte()~=0
    elseif kind==2 then
      constants[index]=tonumber(readBlob())
      if constants[index]==nil then error("invalid Ravel integer constant") end
    elseif kind==3 then
      local number=readBlob()
      if number=="nan" then constants[index]=0/0
      elseif number=="inf" then constants[index]=1/0
      elseif number=="-inf" then constants[index]=-1/0
      else
        constants[index]=tonumber(number)
        if constants[index]==nil then error("invalid Ravel float constant") end
      end
    elseif kind==4 then
      constants[index]=readBlob()
    else
      error("invalid Ravel constant tag")
    end
  end
  local code={}
  local wordCount=readUInt()
  for index=1,wordCount do code[index]=readUInt() end
  if position~=#data+1 then error("trailing Ravel stack capsule data") end
  return {parameterCount,constants,code,opcodeMap,registerCount,dialect}
end
local function getStackProto(id)
  local prototype=STACK_CACHE[id]
  if prototype then
    stackCacheClock=stackCacheClock+1
    STACK_CACHE_AGE[id]=stackCacheClock
    return prototype
  end
  local capsule=C[id]
  if not capsule then error("unknown Ravel stack prototype") end
  prototype=stackDecodeCapsule(capsule[2],capsule[1])
  local oldestId,oldestAge,count=nil,nil,0
  for cachedId,age in pairs(STACK_CACHE_AGE) do
    count=count+1
    if oldestAge==nil or age<oldestAge then oldestId,oldestAge=cachedId,age end
  end
  if count>=STACK_CACHE_LIMIT then
    STACK_CACHE[oldestId]=nil
    STACK_CACHE_AGE[oldestId]=nil
  end
  stackCacheClock=stackCacheClock+1
  STACK_CACHE[id]=prototype
  STACK_CACHE_AGE[id]=stackCacheClock
  return prototype
end

local ENV=_ENV or (getfenv and getfenv())
local unpackValues=table.unpack or unpack
local function packValues(...) return {n=select('#',...),...} end
local run
run=function(id,u,...)
  local p=getStackProto(id)
  local r={}
  local params,k,code,opcodeMap,registerCount,dialect=p[1],p[2],p[3],p[4],p[5],p[6]
  for n=1,params do r[n-1]=select(n,...) end
  local s,top={},0
  local function push(value)
    top=top+1
    s[top]=value
  end
  local function pop()
    if top<1 then error("Ravel stack underflow") end
    local value=s[top]
    s[top]=nil
    top=top-1
    return value
  end
  local pc=1
  while true do
    local base=pc
    local o=opcodeMap[code[base]]
    if not o then error("invalid Ravel stack opcode") end
    pc=pc+code[base+1]
    if o==1 then push(r[code[base+2]])
    elseif o==2 then push(k[code[base+2]])
    elseif o==3 then r[code[base+2]]=pop()
    elseif o==4 then push(ENV[k[code[base+2]]])
    elseif o==5 then ENV[k[code[base+2]]]=pop()
    elseif o==6 then push({})
    elseif o==7 then
      local object,key
      if dialect==0 then key=pop();object=pop() else object=pop();key=pop() end
      push(object[key])
    elseif o==8 then
      local value,key,object
      if dialect==0 then value=pop();key=pop();object=pop()
      else object=pop();key=pop();value=pop() end
      object[key]=value
    elseif o==9 then
      local operation=code[base+2]
      local value=pop()
      if operation==8 then push(-value)
      elseif operation==9 then push(not value)
      elseif operation==10 then push(#value)
      else error("invalid Ravel unary operation") end
    elseif o==10 then
      local operation=code[base+2]
      local left,right
      if dialect==0 then right=pop();left=pop() else left=pop();right=pop() end
      if operation==11 then push(left+right)
      elseif operation==12 then push(left-right)
      elseif operation==13 then push(left*right)
      elseif operation==14 then push(left/right)
      elseif operation==15 then push(left//right)
      elseif operation==16 then push(left%right)
      elseif operation==17 then push(left^right)
      elseif operation==18 then push(left..right)
      elseif operation==19 then push(left==right)
      elseif operation==20 then push(left~=right)
      elseif operation==21 then push(left<right)
      elseif operation==22 then push(left<=right)
      elseif operation==23 then push(left>right)
      elseif operation==24 then push(left>=right)
      else error("invalid Ravel binary operation") end
    elseif o==11 or o==12 then
      local fixedCount,hasSpread=code[base+2],code[base+3]
      local arguments={}
      local count=fixedCount
      if hasSpread~=0 then
        local spread=pop()
        for n=1,spread.n do count=count+1;arguments[count]=spread[n] end
      end
      local fn
      if dialect==0 then
        for n=fixedCount,1,-1 do arguments[n]=pop() end
        fn=pop()
      else
        fn=pop()
        for n=1,fixedCount do arguments[n]=pop() end
      end
      if o==11 then push(fn(unpackValues(arguments,1,count)))
      else push(packValues(fn(unpackValues(arguments,1,count)))) end
    elseif o==13 then
      local target,captureCount=code[base+2],code[base+3]
      local captures={}
      if dialect==0 then for n=captureCount,1,-1 do captures[n]=pop() end
      else for n=1,captureCount do captures[n]=pop() end end
      push(function(...) return run(target,captures,...) end)
    elseif o==14 then pc=code[base+2]
    elseif o==15 then if not pop() then pc=code[base+2] end
    elseif o==16 then if code[base+2]==0 then return else return pop() end
    elseif o==17 then push({pop()})
    elseif o==18 then local cell=pop();push(cell[1])
    elseif o==19 then
      local value,cell
      if dialect==0 then value=pop();cell=pop() else cell=pop();value=pop() end
      cell[1]=value
    elseif o==20 then push(u[code[base+2]])
    elseif o==21 then
      local fixedCount,hasSpread=code[base+2],code[base+3]
      local values={n=fixedCount}
      local count=fixedCount
      if hasSpread~=0 then
        local spread=pop()
        for n=1,spread.n do count=count+1;values[count]=spread[n] end
      end
      if dialect==0 then for n=fixedCount,1,-1 do values[n]=pop() end
      else for n=1,fixedCount do values[n]=pop() end end
      values.n=count
      push(values)
    elseif o==22 then
      local index,values
      if dialect==0 then index=pop();values=pop() else values=pop();index=pop() end
      push(values[index])
    elseif o==23 then push(packValues(select(params+1,...)))
    elseif o==24 then
      local values,start,object
      if dialect==0 then values=pop();start=pop();object=pop()
      else object=pop();start=pop();values=pop() end
      for n=1,values.n do object[start+n-1]=values[n] end
    elseif o==25 then
      local step,limit,index
      if dialect==0 then step=pop();limit=pop();index=pop()
      else index=pop();limit=pop();step=pop() end
      if step>=0 then push(index<=limit) else push(index>=limit) end
    elseif o==26 then
      local values=pop()
      return unpackValues(values,1,values.n)
    else error("invalid Ravel stack opcode") end
  end
end

return run(0,{})
